mapper.select:
select FINPROD_ID id, FINPROD_ABBR text from FIN_PRODUCT where FINPROD_TYPE2 = #{finprodType2}
and (FINPROD_MARKET_ID like concat(concat('%',#{search}),'%') or FINPROD_ABBR like concat(concat('%',#{search}),'%'))
and FINPROD_ID = #{initValue}

    	select sum(count) from (

	    	select count(1) count from FIN_PRODUCT
	    	where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}

    			and FINPROD_MARKET_ID = #{finprodMarketId}


    			and FINPROD_ABBR = #{finprodAbbr}


    			and FINPROD_NAME = #{finprodName}


    			and FINPROD_ID != #{finprodId}

	    	)
